31	/// A routine is a named, persistent, user-owned task with a trigger and an action.
32	#[derive(Debug, Clone, Serialize, Deserialize)]
33	pub struct Routine {
34	    pub id: Uuid,
35	    pub name: String,
36	    pub description: String,
37	    pub user_id: String,
38	    pub enabled: bool,
39	    pub trigger: Trigger,
40	    pub action: RoutineAction,
41	    pub guardrails: RoutineGuardrails,
42	    pub notify: NotifyConfig,
43	
44	    // Runtime state (DB-managed)
45	    pub last_run_at: Option<DateTime<Utc>>,
46	    pub next_fire_at: Option<DateTime<Utc>>,
47	    pub run_count: u64,
48	    pub consecutive_failures: u32,
49	    pub state: serde_json::Value,
50	
51	    pub created_at: DateTime<Utc>,
52	    pub updated_at: DateTime<Utc>,
53	}
