200	    /// Serialize trigger-specific config to JSON for DB storage.
201	    pub fn to_config_json(&self) -> serde_json::Value {
202	        match self {
203	            Trigger::Cron { schedule, timezone } => serde_json::json!({
204	                "schedule": schedule,
205	                "timezone": timezone,
206	            }),
207	            Trigger::Event { channel, pattern } => serde_json::json!({
208	                "pattern": pattern,
209	                "channel": channel,
210	            }),
211	            Trigger::SystemEvent {
212	                source,
213	                event_type,
214	                filters,
215	            } => serde_json::json!({
216	                "source": source,
217	                "event_type": event_type,
218	                "filters": filters,
219	            }),
220	            Trigger::Webhook { path, secret } => serde_json::json!({
