229	/// What happens when a routine fires.
230	#[derive(Debug, Clone, Serialize, Deserialize)]
231	#[serde(tag = "type", rename_all = "snake_case")]
232	pub enum RoutineAction {
233	    /// Single LLM call (optionally with tools). Cheap and fast.
234	    Lightweight {
235	        /// The prompt sent to the LLM.
236	        prompt: String,
237	        /// Workspace paths to load as context (e.g. ["context/priorities.md"]).
238	        #[serde(default)]
239	        context_paths: Vec<String>,
240	        /// Max output tokens (default: 4096).
241	        #[serde(default = "default_max_tokens")]
242	        max_tokens: u32,
243	        /// Enable tool access (default: false for backward compatibility).
244	        /// When true, the LLM can call tools during execution.
245	        /// Tools requiring approval are automatically filtered out.
246	        #[serde(default)]
247	        use_tools: bool,
248	        /// Max tool call rounds (default: 3). Only used when use_tools is true.
249	        #[serde(default = "default_max_tool_rounds")]
250	        max_tool_rounds: u32,
251	    },
252	    /// Full multi-turn worker job with tool access.
253	    FullJob {
254	        /// Job title for the scheduler.
255	        title: String,
256	        /// Job description / initial prompt.
257	        description: String,
258	        /// Max reasoning iterations (default: 10).
259	        #[serde(default = "default_max_iterations")]
260	        max_iterations: u32,
261	    },
262	}
