520	/// Normalize a cron expression to the 7-field format expected by the `cron` crate.
521	///
522	/// The `cron` crate requires: `sec min hour day-of-month month day-of-week year`.
523	/// Standard cron uses 5 fields: `min hour day-of-month month day-of-week`.
524	/// This function auto-expands:
525	/// - 5-field → prepend `0` (seconds) and append `*` (year)
526	/// - 6-field → append `*` (year)
527	/// - 7-field → pass through unchanged
528	pub fn normalize_cron_expression(schedule: &str) -> String {
529	    let trimmed = schedule.trim();
530	    let fields: Vec<&str> = trimmed.split_whitespace().collect();
531	    match fields.len() {
532	        5 => format!("0 {} *", fields.join(" ")),
533	        6 => format!("{} *", fields.join(" ")),
534	        _ => trimmed.to_string(),
535	    }
536	}
537	
538	/// Parse a cron expression and compute the next fire time from now.
539	///
540	/// Accepts standard 5-field, 6-field, or 7-field cron expressions (auto-normalized).
541	/// When `timezone` is provided and valid, the schedule is evaluated in that
542	/// timezone and the result is converted back to UTC. Otherwise UTC is used.
543	pub fn next_cron_fire(
544	    schedule: &str,
545	    timezone: Option<&str>,
546	) -> Result<Option<DateTime<Utc>>, RoutineError> {
547	    let normalized = normalize_cron_expression(schedule);
548	    let cron_schedule =
549	        cron::Schedule::from_str(&normalized).map_err(|e| RoutineError::InvalidCron {
550	            reason: e.to_string(),
551	        })?;
552	    if let Some(tz) = timezone.and_then(crate::timezone::parse_timezone) {
553	        Ok(cron_schedule
554	            .upcoming(tz)
555	            .next()
556	            .map(|dt| dt.with_timezone(&Utc)))
557	    } else {
558	        Ok(cron_schedule.upcoming(Utc).next())
559	    }
560	}
