562	/// Describe common routine cron patterns in plain English.
563	///
564	/// Falls back to `cron: <raw>` for malformed or complex expressions.
565	pub fn describe_cron(schedule: &str, timezone: Option<&str>) -> String {
566	    fn fallback(raw: &str) -> String {
567	        if raw.trim().is_empty() {
568	            "cron: (empty)".to_string()
569	        } else {
570	            format!("cron: {}", raw.trim())
571	        }
572	    }
573	
574	    fn parse_u8_token(token: &str) -> Option<u8> {
575	        token.parse::<u8>().ok()
576	    }
577	
578	    fn parse_step(token: &str) -> Option<u8> {
579	        token
580	            .strip_prefix("*/")
581	            .and_then(parse_u8_token)
582	            .filter(|n| *n > 0)
583	    }
584	
585	    fn weekday_name(dow: &str) -> Option<&'static str> {
586	        let normalized = dow.trim().to_ascii_uppercase();
587	        match normalized.as_str() {
588	            "MON" | "1" => Some("Monday"),
589	            "TUE" | "2" => Some("Tuesday"),
590	            "WED" | "3" => Some("Wednesday"),
591	            "THU" | "4" => Some("Thursday"),
592	            "FRI" | "5" => Some("Friday"),
593	            "SAT" | "6" => Some("Saturday"),
594	            "SUN" | "0" | "7" => Some("Sunday"),
595	            _ => None,
596	        }
597	    }
598	
599	    fn format_time(hour: u8, minute: u8) -> String {
600	        if hour == 0 && minute == 0 {
601	            return "midnight".to_string();
602	        }
603	        let (display_hour, am_pm) = match hour {
604	            0 => (12, "AM"),
605	            1..=11 => (hour, "AM"),
606	            12 => (12, "PM"),
607	            _ => (hour - 12, "PM"),
608	        };
609	        format!("{display_hour}:{minute:02} {am_pm}")
610	    }
611	
612	    fn ordinal(n: u8) -> String {
613	        let suffix = if (11..=13).contains(&(n % 100)) {
614	            "th"
615	        } else {
616	            match n % 10 {
617	                1 => "st",
618	                2 => "nd",
619	                3 => "rd",
620	                _ => "th",
621	            }
622	        };
623	        format!("{n}{suffix}")
624	    }
625	
626	    fn describe_inner(raw: &str) -> Option<String> {
627	        let fields: Vec<&str> = raw.split_whitespace().collect();
628	        let (sec, min, hour, dom, month, dow, year) = match fields.len() {
629	            5 => (
630	                "0", fields[0], fields[1], fields[2], fields[3], fields[4], None,
631	            ),
632	            6 => (
633	                fields[0], fields[1], fields[2], fields[3], fields[4], fields[5], None,
634	            ),
635	            7 => (
636	                fields[0],
637	                fields[1],
638	                fields[2],
639	                fields[3],
640	                fields[4],
641	                fields[5],
642	                Some(fields[6]),
643	            ),
644	            _ => return None,
645	        };
646	
647	        if year.is_some_and(|v| v != "*") {
648	            return None;
649	        }
650	
651	        if sec == "0"
652	            && hour == "*"
653	            && dom == "*"
654	            && month == "*"
655	            && dow == "*"
656	            && let Some(step) = parse_step(min)
657	        {
658	            return Some(match step {
659	                1 => "Every minute".to_string(),
660	                n => format!("Every {n} minutes"),
661	            });
662	        }
663	
664	        if sec == "0"
665	            && min == "0"
666	            && dom == "*"
667	            && month == "*"
668	            && dow == "*"
669	            && let Some(step) = parse_step(hour)
670	        {
671	            return Some(match step {
672	                1 => "Every hour".to_string(),
673	                n => format!("Every {n} hours"),
674	            });
675	        }
676	
677	        let hour = parse_u8_token(hour).filter(|h| *h <= 23)?;
678	        let minute = parse_u8_token(min).filter(|m| *m <= 59)?;
679	        let time = format_time(hour, minute);
680	        let time_phrase = if time == "midnight" {
681	            "at midnight".to_string()
682	        } else {
683	            format!("at {time}")
684	        };
685	
686	        if sec == "0" && dom == "*" && month == "*" && dow == "*" {
687	            return Some(format!("Daily {time_phrase}"));
688	        }
689	
690	        if sec == "0" && dom == "*" && month == "*" && dow.eq_ignore_ascii_case("MON-FRI") {
691	            return Some(format!("Weekdays {time_phrase}"));
692	        }
693	
694	        if sec == "0"
695	            && dom == "*"
696	            && month == "*"
697	            && let Some(day_name) = weekday_name(dow)
698	        {
699	            return Some(format!("Every {day_name} {time_phrase}"));
700	        }
701	
702	        if sec == "0"
703	            && month == "*"
704	            && dow == "*"
705	            && let Some(day_of_month) = parse_u8_token(dom).filter(|d| (1..=31).contains(d))
706	        {
707	            return Some(format!(
708	                "{} of every month {time_phrase}",
709	                ordinal(day_of_month)
710	            ));
711	        }
712	
713	        None
714	    }
715	
716	    let mut description = describe_inner(schedule).unwrap_or_else(|| fallback(schedule));
717	    if let Some(tz) = timezone.map(str::trim).filter(|tz| !tz.is_empty()) {
718	        description.push_str(" (");
719	        description.push_str(tz);
720	        description.push(')');
721	    }
722	    description
723	}
