158	    /// Refresh the in-memory event trigger cache from DB.
159	    pub async fn refresh_event_cache(&self) {
160	        match self.store.list_event_routines().await {
161	            Ok(routines) => {
162	                let mut cache = Vec::new();
163	                for routine in routines {
164	                    match &routine.trigger {
165	                        Trigger::Event { pattern, .. } => {
166	                            // Use RegexBuilder with size limit to prevent ReDoS
167	                            // from user-supplied patterns (issue #825).
168	                            match regex::RegexBuilder::new(pattern)
169	                                .size_limit(64 * 1024) // 64KB compiled size limit
170	                                .build()
171	                            {
172	                                Ok(re) => cache.push(EventMatcher::Message {
173	                                    routine: routine.clone(),
174	                                    regex: re,
175	                                }),
176	                                Err(e) => {
177	                                    tracing::warn!(
178	                                        routine = %routine.name,
179	                                        "Invalid or too complex event regex '{}': {}",
180	                                        pattern, e
181	                                    );
182	                                }
183	                            }
184	                        }
185	                        Trigger::SystemEvent { .. } => {
186	                            cache.push(EventMatcher::System {
187	                                routine: routine.clone(),
188	                            });
189	                        }
190	                        _ => {}
191	                    }
192	                }
193	                let count = cache.len();
194	                *self.event_cache.write().await = cache;
195	                tracing::trace!("Refreshed event cache: {} routines", count);
196	            }
197	            Err(e) => {
198	                tracing::error!("Failed to refresh event cache: {}", e);
199	            }
200	        }
201	    }
