424	    /// Check all due cron routines and fire them. Called by the cron ticker.
425	    pub async fn check_cron_triggers(&self) {
426	        let routines = match self.store.list_due_cron_routines().await {
427	            Ok(r) => r,
428	            Err(e) => {
429	                tracing::error!("Failed to load due cron routines: {}", e);
430	                return;
431	            }
432	        };
433	
434	        for routine in routines {
435	            if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {
436	                tracing::warn!("Global max concurrent routines reached, skipping remaining");
437	                break;
438	            }
439	
440	            if !self.check_cooldown(&routine) {
441	                continue;
442	            }
443	
444	            if !self.check_concurrent(&routine).await {
445	                continue;
446	            }
447	
448	            let detail = if let Trigger::Cron { ref schedule, .. } = routine.trigger {
449	                Some(schedule.clone())
450	            } else {
451	                None
452	            };
453	
454	            self.spawn_fire(routine, "cron", detail);
455	        }
