556	    /// Finalize a dispatched routine run: update DB, update routine runtime,
557	    /// persist to conversation thread, and send notification.
558	    async fn complete_dispatched_run(&self, run: &RoutineRun, status: RunStatus, summary: &str) {
559	        // Complete the run record in DB
560	        if let Err(e) = self
561	            .store
562	            .complete_routine_run(run.id, status, Some(summary), None)
563	            .await
564	        {
565	            tracing::error!(
566	                run_id = %run.id,
567	                "Failed to complete dispatched routine run: {}", e
568	            );
569	            return;
570	        }
571	
572	        tracing::info!(
573	            run_id = %run.id,
574	            status = %status,
575	            "Finalized dispatched routine run"
576	        );
577	
578	        // Load the routine to update consecutive_failures and send notification
579	        let routine = match self.store.get_routine(run.routine_id).await {
580	            Ok(Some(r)) => r,
581	            Ok(None) => {
582	                tracing::warn!(
583	                    run_id = %run.id,
584	                    routine_id = %run.routine_id,
585	                    "Routine not found for dispatched run finalization"
586	                );
587	                return;
588	            }
589	            Err(e) => {
590	                tracing::error!(
591	                    run_id = %run.id,
592	                    "Failed to load routine for dispatched run: {}", e
593	                );
594	                return;
595	            }
596	        };
597	
598	        // Update runtime fields. In crash recovery, execute_routine() never
599	        // reached its normal runtime update, so we must advance all fields here.
600	        let new_failures = if status == RunStatus::Failed {
601	            routine.consecutive_failures + 1
602	        } else {
603	            0
604	        };
605	
606	        let now = Utc::now();
607	        let next_fire = if let Trigger::Cron {
608	            ref schedule,
609	            ref timezone,
610	        } = routine.trigger
611	        {
612	            next_cron_fire(schedule, timezone.as_deref()).unwrap_or(None)
613	        } else {
614	            None
615	        };
616	
617	        if let Err(e) = self
618	            .store
619	            .update_routine_runtime(
620	                routine.id,
621	                now,
622	                next_fire,
623	                routine.run_count + 1,
624	                new_failures,
625	                &routine.state,
626	            )
627	            .await
628	        {
629	            tracing::error!(
630	                routine = %routine.name,
631	                "Failed to update routine runtime after dispatched run: {}", e
632	            );
633	        }
634	
635	        // Persist result to the routine's conversation thread
636	        let thread_id = match self
637	            .store
638	            .get_or_create_routine_conversation(routine.id, &routine.name, &routine.user_id)
639	            .await
640	        {
641	            Ok(conv_id) => {
642	                let msg = format!("[dispatched] {}: {}", status, summary);
643	                if let Err(e) = self
644	                    .store
645	                    .add_conversation_message(conv_id, "assistant", &msg)
646	                    .await
647	                {
648	                    tracing::error!(
649	                        routine = %routine.name,
650	                        "Failed to persist dispatched run message: {}", e
651	                    );
652	                }
653	                Some(conv_id.to_string())
654	            }
655	            Err(e) => {
656	                tracing::error!(
657	                    routine = %routine.name,
658	                    "Failed to get routine conversation: {}", e
659	                );
660	                None
661	            }
662	        };
663	
664	        // Send notification
665	        send_notification(
666	            &self.notify_tx,
667	            &routine.notify,
668	            &routine.user_id,
669	            &routine.name,
670	            status,
671	            Some(summary),
672	            thread_id.as_deref(),
673	        )
674	        .await;
675	
676	        // Note: we do NOT decrement running_count here. In normal flow,
677	        // execute_routine() handles that after FullJobWatcher returns.
678	        // This sync path only runs for crash recovery (process restarted),
679	        // where running_count was already reset to 0.
680	    }
