682	    /// Fire a routine manually (from tool call or CLI).
683	    ///
684	    /// Bypasses cooldown checks (those only apply to cron/event triggers).
685	    /// Still enforces enabled check and concurrent run limit.
686	    pub async fn fire_manual(
687	        &self,
688	        routine_id: Uuid,
689	        user_id: Option<&str>,
690	    ) -> Result<Uuid, RoutineError> {
691	        let routine = self
692	            .store
693	            .get_routine(routine_id)
694	            .await
695	            .map_err(|e| RoutineError::Database {
696	                reason: e.to_string(),
697	            })?
698	            .ok_or(RoutineError::NotFound { id: routine_id })?;
699	
700	        // Enforce ownership when a user_id is provided (gateway calls).
701	        if let Some(uid) = user_id
702	            && routine.user_id != uid
703	        {
704	            return Err(RoutineError::NotAuthorized { id: routine_id });
705	        }
706	
707	        if !routine.enabled {
708	            return Err(RoutineError::Disabled {
709	                name: routine.name.clone(),
710	            });
711	        }
712	
713	        if !self.check_concurrent(&routine).await {
714	            return Err(RoutineError::MaxConcurrent {
715	                name: routine.name.clone(),
716	            });
717	        }
718	
719	        let run_id = Uuid::new_v4();
720	        let run = RoutineRun {
721	            id: run_id,
722	            routine_id: routine.id,
723	            trigger_type: "manual".to_string(),
724	            trigger_detail: None,
725	            started_at: Utc::now(),
726	            completed_at: None,
727	            status: RunStatus::Running,
728	            result_summary: None,
729	            tokens_used: None,
730	            job_id: None,
731	            created_at: Utc::now(),
732	        };
733	
734	        if let Err(e) = self.store.create_routine_run(&run).await {
735	            return Err(RoutineError::Database {
736	                reason: format!("failed to create run record: {e}"),
737	            });
738	        }
739	
740	        // Execute inline for manual triggers (caller wants to wait)
741	        let engine = EngineContext {
742	            config: self.config.clone(),
743	            store: self.store.clone(),
744	            llm: self.llm.clone(),
745	            workspace: self.workspace.clone(),
746	            notify_tx: self.notify_tx.clone(),
747	            running_count: self.running_count.clone(),
748	            scheduler: self.scheduler.clone(),
749	            extension_manager: self.extension_manager.clone(),
750	            tools: self.tools.clone(),
751	            safety: self.safety.clone(),
752	            sandbox_readiness: self.sandbox_readiness,
753	        };
754	
755	        tokio::spawn(async move {
756	            execute_routine(engine, routine, run).await;
757	        });
758	
759	        Ok(run_id)
760	    }
