762	    /// Fire a routine from a webhook trigger.
763	    ///
764	    /// Similar to `fire_manual` but records the trigger as `"webhook"` with the
765	    /// webhook path as detail. Skips ownership check (auth is via webhook secret).
766	    /// Enforces enabled check, cooldown, and concurrent run limit.
767	    pub async fn fire_webhook(
768	        &self,
769	        routine_id: Uuid,
770	        webhook_path: &str,
771	    ) -> Result<Uuid, RoutineError> {
772	        let routine = self
773	            .store
774	            .get_routine(routine_id)
775	            .await
776	            .map_err(|e| RoutineError::Database {
777	                reason: e.to_string(),
778	            })?
779	            .ok_or(RoutineError::NotFound { id: routine_id })?;
780	
781	        if !routine.enabled {
782	            return Err(RoutineError::Disabled {
783	                name: routine.name.clone(),
784	            });
785	        }
786	
787	        if !self.check_cooldown(&routine) {
788	            return Err(RoutineError::Cooldown {
789	                name: routine.name.clone(),
790	            });
791	        }
792	
793	        if !self.check_concurrent(&routine).await {
794	            return Err(RoutineError::MaxConcurrent {
795	                name: routine.name.clone(),
796	            });
797	        }
798	
799	        if self.running_count.load(Ordering::Relaxed) >= self.config.max_concurrent_routines {
800	            return Err(RoutineError::MaxConcurrent {
801	                name: routine.name.clone(),
802	            });
803	        }
804	
805	        let run_id = Uuid::new_v4();
806	        let run = RoutineRun {
807	            id: run_id,
808	            routine_id: routine.id,
809	            trigger_type: "webhook".to_string(),
810	            trigger_detail: Some(webhook_path.to_string()),
811	            started_at: Utc::now(),
812	            completed_at: None,
813	            status: RunStatus::Running,
814	            result_summary: None,
815	            tokens_used: None,
816	            job_id: None,
817	            created_at: Utc::now(),
818	        };
819	
820	        if let Err(e) = self.store.create_routine_run(&run).await {
821	            return Err(RoutineError::Database {
822	                reason: format!("failed to create run record: {e}"),
823	            });
824	        }
825	
826	        let engine = EngineContext {
827	            config: self.config.clone(),
828	            store: self.store.clone(),
829	            llm: self.llm.clone(),
830	            workspace: self.workspace.clone(),
831	            notify_tx: self.notify_tx.clone(),
832	            running_count: self.running_count.clone(),
833	            scheduler: self.scheduler.clone(),
834	            extension_manager: self.extension_manager.clone(),
835	            tools: self.tools.clone(),
836	            safety: self.safety.clone(),
837	            sandbox_readiness: self.sandbox_readiness,
838	        };
839	
840	        tokio::spawn(async move {
841	            execute_routine(engine, routine, run).await;
842	        });
843	
844	        Ok(run_id)
845	    }
