902	            Ok(count) => count < routine.guardrails.max_concurrent as i64,
903	            Err(e) => {
904	                tracing::error!(
905	                    routine = %routine.name,
906	                    "Failed to check concurrent runs: {}", e
907	                );
908	                false
909	            }
910	        }
911	    }
