914	/// Watches a dispatched full_job until the linked scheduler job completes.
915	///
916	/// Polls `store.get_job(job_id)` at a fixed interval until the job leaves
917	/// an active state (Pending/InProgress/Stuck). Maps the final `JobState` to
918	/// a `RunStatus` for the routine run.
919	struct FullJobWatcher {
920	    store: Arc<dyn Database>,
921	    job_id: Uuid,
922	    routine_name: String,
923	}
924	
925	impl FullJobWatcher {
926	    /// Poll interval between DB checks.
927	    const POLL_INTERVAL: Duration = Duration::from_secs(5);
928	    /// Safety ceiling: 24 hours, derived from POLL_INTERVAL.
929	    const MAX_POLLS: u32 = (24 * 60 * 60) / Self::POLL_INTERVAL.as_secs() as u32;
930	
931	    fn new(store: Arc<dyn Database>, job_id: Uuid, routine_name: String) -> Self {
932	        Self {
933	            store,
934	            job_id,
935	            routine_name,
936	        }
937	    }
938	
939	    /// Block until the linked job finishes and return the mapped status + summary.
940	    async fn wait_for_completion(&self) -> (RunStatus, Option<String>) {
941	        let mut polls = 0u32;
942	
943	        let final_status = loop {
944	            // Check job state before sleeping so we finalize promptly
945	            // if the job is already done (e.g. fast-failing jobs).
946	            match self.store.get_job(self.job_id).await {
947	                Ok(Some(job_ctx)) => {
948	                    // Use is_parallel_blocking (Pending/InProgress/Stuck) instead
949	                    // of is_active (!is_terminal) because routine jobs typically
950	                    // stop at Completed — which is NOT terminal but IS finished
951	                    // from an execution standpoint.
952	                    if !job_ctx.state.is_parallel_blocking() {
953	                        break Self::map_job_state(&job_ctx.state);
954	                    }
955	                }
956	                Ok(None) => {
957	                    tracing::warn!(
958	                        routine = %self.routine_name,
959	                        job_id = %self.job_id,
960	                        "full_job disappeared from DB while polling"
961	                    );
962	                    break RunStatus::Failed;
963	                }
964	                Err(e) => {
965	                    tracing::error!(
966	                        routine = %self.routine_name,
967	                        job_id = %self.job_id,
968	                        "Error polling full_job state: {}", e
969	                    );
970	                    break RunStatus::Failed;
971	                }
972	            }
973	
974	            polls += 1;
975	            if polls >= Self::MAX_POLLS {
976	                tracing::error!(
977	                    routine = %self.routine_name,
978	                    job_id = %self.job_id,
979	                    "full_job timed out after 24 hours, treating as failed"
980	                );
981	                break RunStatus::Failed;
982	            }
983	
984	            tokio::time::sleep(Self::POLL_INTERVAL).await;
985	        };
986	
987	        let summary = format!("Job {} finished ({})", self.job_id, final_status);
988	        (final_status, Some(summary))
989	    }
990	
991	    fn map_job_state(state: &crate::context::JobState) -> RunStatus {
992	        use crate::context::JobState;
993	        match state {
994	            JobState::Failed | JobState::Cancelled => RunStatus::Failed,
995	            _ => RunStatus::Ok, // Completed / Submitted / Accepted
996	        }
997	    }
998	}
