1000	/// Shared context passed to the execution function.
1001	struct EngineContext {
1002	    config: RoutineConfig,
1003	    store: Arc<dyn Database>,
1004	    llm: Arc<dyn LlmProvider>,
1005	    workspace: Arc<Workspace>,
1006	    notify_tx: mpsc::Sender<OutgoingResponse>,
1007	    running_count: Arc<AtomicUsize>,
1008	    scheduler: Option<Arc<Scheduler>>,
1009	    extension_manager: Option<Arc<ExtensionManager>>,
1010	    tools: Arc<ToolRegistry>,
1011	    safety: Arc<SafetyLayer>,
1012	    sandbox_readiness: SandboxReadiness,
1013	}
