1015	/// Execute a routine run. Handles both lightweight and full_job modes.
1016	async fn execute_routine(ctx: EngineContext, routine: Routine, run: RoutineRun) {
1017	    // Increment running count (atomic: survives panics in the execution below)
1018	    ctx.running_count.fetch_add(1, Ordering::Relaxed);
1019	
1020	    let result = match &routine.action {
1021	        RoutineAction::Lightweight {
1022	            prompt,
1023	            context_paths,
1024	            max_tokens,
1025	            use_tools,
1026	            max_tool_rounds,
1027	        } => {
1028	            execute_lightweight(
1029	                &ctx,
1030	                &routine,
1031	                prompt,
1032	                context_paths,
1033	                *max_tokens,
1034	                *use_tools,
1035	                *max_tool_rounds,
1036	            )
1037	            .await
1038	        }
1039	        RoutineAction::FullJob {
1040	            title,
1041	            description,
1042	            max_iterations,
1043	        } => {
1044	            let execution = FullJobExecutionConfig {
1045	                title,
1046	                description,
1047	                max_iterations: *max_iterations,
1048	            };
1049	            execute_full_job(&ctx, &routine, &run, &execution).await
1050	        }
1051	    };
1052	
1053	    // Decrement running count
1054	    ctx.running_count.fetch_sub(1, Ordering::Relaxed);
1055	
1056	    // Process result
1057	    let (status, summary, tokens) = match result {
1058	        Ok(execution) => execution,
1059	        Err(e) => {
1060	            tracing::error!(routine = %routine.name, "Execution failed: {}", e);
1061	            (RunStatus::Failed, Some(e.to_string()), None)
1062	        }
1063	    };
1064	
1065	    // Complete the run record
1066	    if let Err(e) = ctx
1067	        .store
1068	        .complete_routine_run(run.id, status, summary.as_deref(), tokens)
1069	        .await
1070	    {
1071	        tracing::error!(routine = %routine.name, "Failed to complete run record: {}", e);
1072	    }
1073	
1074	    // Update routine runtime state
1075	    let now = Utc::now();
1076	    let next_fire = if let Trigger::Cron {
1077	        ref schedule,
1078	        ref timezone,
1079	    } = routine.trigger
1080	    {
1081	        next_cron_fire(schedule, timezone.as_deref()).unwrap_or(None)
1082	    } else {
1083	        None
1084	    };
1085	
1086	    let new_failures = if status == RunStatus::Failed {
1087	        routine.consecutive_failures + 1
1088	    } else {
1089	        0
1090	    };
1091	
1092	    if let Err(e) = ctx
1093	        .store
1094	        .update_routine_runtime(
1095	            routine.id,
1096	            now,
1097	            next_fire,
1098	            routine.run_count + 1,
1099	            new_failures,
1100	            &routine.state,
1101	        )
1102	        .await
1103	    {
1104	        tracing::error!(routine = %routine.name, "Failed to update runtime state: {}", e);
1105	    }
1106	
1107	    // Persist routine result to its dedicated conversation thread
1108	    let thread_id = match ctx
1109	        .store
1110	        .get_or_create_routine_conversation(routine.id, &routine.name, &routine.user_id)
1111	        .await
1112	    {
1113	        Ok(conv_id) => {
1114	            tracing::debug!(
1115	                routine = %routine.name,
1116	                routine_id = %routine.id,
1117	                conversation_id = %conv_id,
1118	                "Resolved routine conversation thread"
1119	            );
1120	            // Record the run result as a conversation message
1121	            let msg = match (&summary, status) {
1122	                (Some(s), _) => format!("[{}] {}: {}", run.trigger_type, status, s),
1123	                (None, _) => format!("[{}] {}", run.trigger_type, status),
1124	            };
1125	            if let Err(e) = ctx
1126	                .store
1127	                .add_conversation_message(conv_id, "assistant", &msg)
1128	                .await
1129	            {
1130	                tracing::error!(routine = %routine.name, "Failed to persist routine message: {}", e);
1131	            }
1132	            Some(conv_id.to_string())
1133	        }
1134	        Err(e) => {
1135	            tracing::error!(routine = %routine.name, "Failed to get routine conversation: {}", e);
1136	            None
1137	        }
1138	    };
1139	
1140	    // Send notifications based on config
1141	    send_notification(
1142	        &ctx.notify_tx,
1143	        &routine.notify,
1144	        &routine.user_id,
1145	        &routine.name,
1146	        status,
1147	        summary.as_deref(),
1148	        thread_id.as_deref(),
1149	    )
1150	    .await;
1151	}
