1153	/// Sanitize a routine name for use in workspace paths.
1154	/// Only keeps alphanumeric, dash, and underscore characters; replaces everything else.
1155	fn sanitize_routine_name(name: &str) -> String {
1156	    name.chars()
1157	        .map(|c| {
1158	            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
1159	                c
1160	            } else {
1161	                '_'
1162	            }
1163	        })
1164	        .collect()
1165	}
