1167	/// Execute a full-job routine by dispatching to the scheduler.
1168	///
1169	/// Fire-and-forget: creates a job via `Scheduler::dispatch_job` (which handles
1170	/// creation, metadata, persistence, and scheduling), links the routine run to
1171	/// the job, then watches it via `FullJobWatcher` until it reaches a
1172	/// non-active state (not Pending/InProgress/Stuck). Returns the final
1173	/// `RunStatus` mapped from the job outcome. This keeps the routine run
1174	/// active for the full job lifetime so concurrency guardrails apply.
1175	struct FullJobExecutionConfig<'a> {
1176	    title: &'a str,
1177	    description: &'a str,
1178	    max_iterations: u32,
1179	}
1180	
1181	async fn execute_full_job(
1182	    ctx: &EngineContext,
1183	    routine: &Routine,
1184	    run: &RoutineRun,
1185	    execution: &FullJobExecutionConfig<'_>,
1186	) -> Result<(RunStatus, Option<String>, Option<i32>), RoutineError> {
1187	    match ctx.sandbox_readiness {
1188	        SandboxReadiness::Available => {}
1189	        SandboxReadiness::DisabledByConfig => {
1190	            return Err(RoutineError::JobDispatchFailed {
1191	                reason: "Sandboxing is disabled (SANDBOX_ENABLED=false). \
1192	                         Full-job routines require sandbox."
1193	                    .to_string(),
1194	            });
1195	        }
1196	        SandboxReadiness::DockerUnavailable => {
1197	            return Err(RoutineError::JobDispatchFailed {
1198	                reason: "Sandbox is enabled but Docker is not available. \
1199	                         Install Docker or set SANDBOX_ENABLED=false."
1200	                    .to_string(),
1201	            });
1202	        }
1203	    }
1204	
1205	    let scheduler = ctx
1206	        .scheduler
1207	        .as_ref()
1208	        .ok_or_else(|| RoutineError::JobDispatchFailed {
1209	            reason: "scheduler not available".to_string(),
1210	        })?;
1211	
1212	    let mut metadata = serde_json::json!({
1213	        "max_iterations": execution.max_iterations,
1214	        "owner_id": routine.user_id
1215	    });
1216	    // Carry the routine's notify config in job metadata so the message tool
1217	    // can resolve channel/target per-job without global state mutation.
1218	    if let Some(channel) = &routine.notify.channel {
1219	        metadata["notify_channel"] = serde_json::json!(channel);
1220	    }
1221	    metadata["notify_user"] = serde_json::json!(&routine.notify.user);
1222	
1223	    let job_id = scheduler
1224	        .dispatch_job(
1225	            &routine.user_id,
1226	            execution.title,
1227	            execution.description,
1228	            Some(metadata),
1229	        )
1230	        .await
1231	        .map_err(|e| RoutineError::JobDispatchFailed {
1232	            reason: format!("failed to dispatch job: {e}"),
1233	        })?;
1234	
1235	    // Link the routine run to the dispatched job.
1236	    // This MUST succeed — if it fails, sync_dispatched_runs() will never find
1237	    // this run (it filters on job_id IS NOT NULL), leaving it stuck as 'running'
1238	    // with running_count permanently elevated.
1239	    ctx.store
1240	        .link_routine_run_to_job(run.id, job_id)
1241	        .await
1242	        .map_err(|e| RoutineError::Database {
1243	            reason: format!("failed to link run to job: {e}"),
1244	        })?;
1245	
1246	    tracing::info!(
1247	        routine = %routine.name,
1248	        job_id = %job_id,
1249	        max_iterations = execution.max_iterations,
1250	        "Dispatched full job for routine, watching for completion"
1251	    );
1252	
1253	    // Watch the job until it finishes — keeps the routine run active
1254	    // so concurrency guardrails (running_count, routine_runs status)
1255	    // remain enforced for the full job lifetime.
1256	    let watcher = FullJobWatcher::new(ctx.store.clone(), job_id, routine.name.clone());
1257	    let (status, summary) = watcher.wait_for_completion().await;
1258	    Ok((status, summary, None))
1259	}
