1261	/// Execute a lightweight routine with optional tool support.
1262	///
1263	/// If tools are enabled, this runs a simplified agentic loop (max 3-5 iterations).
1264	/// If tools are disabled, this does a single LLM call (original behavior).
1265	async fn execute_lightweight(
1266	    ctx: &EngineContext,
1267	    routine: &Routine,
1268	    prompt: &str,
1269	    context_paths: &[String],
1270	    max_tokens: u32,
1271	    use_tools: bool,
1272	    max_tool_rounds: u32,
1273	) -> Result<(RunStatus, Option<String>, Option<i32>), RoutineError> {
1274	    // Load context from workspace
1275	    let mut context_parts = Vec::new();
1276	    for path in context_paths {
1277	        match ctx.workspace.read(path).await {
1278	            Ok(doc) => {
1279	                context_parts.push(format!("## {}\n\n{}", path, doc.content));
1280	            }
1281	            Err(e) => {
1282	                tracing::debug!(
1283	                    routine = %routine.name,
1284	                    "Failed to read context path {}: {}", path, e
1285	                );
1286	            }
1287	        }
1288	    }
1289	
1290	    // Load routine state from workspace (name sanitized to prevent path traversal)
1291	    let safe_name = sanitize_routine_name(&routine.name);
1292	    let state_path = format!("routines/{safe_name}/state.md");
1293	    let state_content = match ctx.workspace.read(&state_path).await {
1294	        Ok(doc) => Some(doc.content),
1295	        Err(_) => None,
1296	    };
1297	
1298	    let full_prompt = build_lightweight_prompt(
1299	        prompt,
1300	        &context_parts,
1301	        state_content.as_deref(),
1302	        &routine.notify,
1303	        use_tools,
1304	    );
1305	
1306	    // Get system prompt
1307	    let system_prompt = match ctx.workspace.system_prompt().await {
1308	        Ok(p) => p,
1309	        Err(e) => {
1310	            tracing::warn!(routine = %routine.name, "Failed to get system prompt: {}", e);
1311	            String::new()
1312	        }
1313	    };
1314	
1315	    // Determine max_tokens from model metadata with fallback
1316	    let effective_max_tokens = match ctx.llm.model_metadata().await {
1317	        Ok(meta) => {
1318	            let from_api = meta.context_length.map(|ctx| ctx / 2).unwrap_or(max_tokens);
1319	            from_api.max(max_tokens)
1320	        }
1321	        Err(_) => max_tokens,
1322	    };
1323	
1324	    // If tools are enabled (both globally and per-routine), use the tool execution loop
1325	    if use_tools && ctx.config.lightweight_tools_enabled {
1326	        execute_lightweight_with_tools(
1327	            ctx,
1328	            routine,
1329	            &system_prompt,
1330	            &full_prompt,
1331	            effective_max_tokens,
1332	            max_tool_rounds,
1333	        )
1334	        .await
1335	    } else {
1336	        execute_lightweight_no_tools(
1337	            ctx,
1338	            routine,
1339	            &system_prompt,
1340	            &full_prompt,
1341	            effective_max_tokens,
1342	        )
1343	        .await
1344	    }
1345	}
