1347	/// Sanitize a user-controlled string before interpolation into an LLM prompt.
1348	/// Strips newlines (which could break prompt structure) and truncates to a
1349	/// reasonable length to limit abuse surface.
1350	fn sanitize_prompt_field(value: &str) -> String {
1351	    const MAX_LEN: usize = 128;
1352	    value
1353	        .chars()
1354	        .filter(|&c| c != '\n' && c != '\r')
1355	        .take(MAX_LEN)
1356	        .map(|c| if c == '`' { '\'' } else { c })
1357	        .collect()
1358	}
1359	
1360	fn build_lightweight_prompt(
1361	    prompt: &str,
1362	    context_parts: &[String],
1363	    state_content: Option<&str>,
1364	    notify: &NotifyConfig,
1365	    use_tools: bool,
1366	) -> String {
1367	    let mut full_prompt = String::new();
1368	    full_prompt.push_str(prompt);
1369	
1370	    if notify.on_attention {
1371	        full_prompt.push_str("\n\n---\n\n# Delivery\n\n");
1372	        full_prompt.push_str(
1373	            "If you reply with anything other than ROUTINE_OK, the host will deliver your \
1374	             reply as the routine notification. Return the message exactly as it should be sent.\n",
1375	        );
1376	
1377	        if let Some(channel) = notify.channel.as_deref() {
1378	            let sanitized = sanitize_prompt_field(channel);
1379	            full_prompt.push_str(&format!(
