1422	async fn execute_lightweight_no_tools(
1423	    ctx: &EngineContext,
1424	    _routine: &Routine,
1425	    system_prompt: &str,
1426	    full_prompt: &str,
1427	    effective_max_tokens: u32,
1428	) -> Result<(RunStatus, Option<String>, Option<i32>), RoutineError> {
1429	    let messages = if system_prompt.is_empty() {
1430	        vec![ChatMessage::user(full_prompt)]
1431	    } else {
1432	        vec![
1433	            ChatMessage::system(system_prompt),
1434	            ChatMessage::user(full_prompt),
1435	        ]
1436	    };
