1465	/// Handle a text-only LLM response in lightweight routine execution.
1466	///
1467	/// Checks for the ROUTINE_OK sentinel, validates content, and returns appropriate status.
1468	fn handle_text_response(
1469	    content: &str,
1470	    finish_reason: FinishReason,
1471	    total_input_tokens: u32,
1472	    total_output_tokens: u32,
1473	) -> Result<(RunStatus, Option<String>, Option<i32>), RoutineError> {
1474	    let content = content.trim();
1475	
1476	    // Empty content guard — carry consumed tokens so the retry loop can
1477	    // accumulate them even when the response shape is invalid.
1478	    if content.is_empty() {
1479	        let consumed = tokens_to_option(total_input_tokens, total_output_tokens);
1480	        return if finish_reason == FinishReason::Length {
1481	            Err(RoutineError::TruncatedResponse {
1482	                partial_tokens: consumed,
1483	            })
1484	        } else {
1485	            Err(RoutineError::EmptyResponse {
1486	                partial_tokens: consumed,
1487	            })
1488	        };
1489	    }
1490	
1491	    // Check for the "nothing to do" sentinel (exact match on trimmed content).
1492	    if content == "ROUTINE_OK" {
1493	        let total_tokens = Some((total_input_tokens + total_output_tokens) as i32);
1494	        return Ok((RunStatus::Ok, None, total_tokens));
1495	    }
1496	
1497	    let total_tokens = Some((total_input_tokens + total_output_tokens) as i32);
1498	    Ok((
1499	        RunStatus::Attention,
1500	        Some(content.to_string()),
1501	        total_tokens,
1502	    ))
1503	}
