1505	/// Execute a lightweight routine with tool execution support (agentic loop).
1506	///
1507	/// This is a simplified version of the full dispatcher loop:
1508	/// - Max 3-5 iterations (configurable)
1509	/// - Sequential tool execution (not parallel)
1510	/// - Uses the owner's live autonomous tool scope when lightweight tools are enabled
1511	/// - Auto-approval of non-Always tools
1512	/// - No hooks or approval dialogs
1513	async fn execute_lightweight_with_tools(
1514	    ctx: &EngineContext,
1515	    routine: &Routine,
1516	    system_prompt: &str,
1517	    full_prompt: &str,
1518	    effective_max_tokens: u32,
1519	    max_tool_rounds: u32,
1520	) -> Result<(RunStatus, Option<String>, Option<i32>), RoutineError> {
1521	    let mut messages = if system_prompt.is_empty() {
1522	        vec![ChatMessage::user(full_prompt)]
1523	    } else {
1524	        vec![
1525	            ChatMessage::system(system_prompt),
1526	            ChatMessage::user(full_prompt),
1527	        ]
1528	    };
1529	
1530	    let max_iterations = max_tool_rounds
1531	        .min(ctx.config.lightweight_max_iterations)
1532	        .min(5);
1533	    let mut iteration = 0;
1534	    let mut total_input_tokens = 0;
1535	    let mut total_output_tokens = 0;
1536	
1537	    // Create a minimal job context for tool execution with unique run ID
1538	    let run_id = Uuid::new_v4();
1539	    let job_ctx = JobContext {
1540	        job_id: run_id,
1541	        user_id: routine.user_id.clone(),
1542	        title: "Lightweight Routine".to_string(),
1543	        description: routine.name.clone(),
1544	        ..Default::default()
1545	    };
1546	    let allowed_tools =
1547	        autonomous_allowed_tool_names(&ctx.tools, ctx.extension_manager.as_ref(), &routine.user_id)
1548	            .await;
1549	
1550	    loop {
1551	        iteration += 1;
1552	
1553	        // Force text-only response at iteration limit
1554	        let force_text = iteration >= max_iterations;
1555	
1556	        if force_text {
1557	            // Final iteration: no tools, just get text response
1558	            let request = CompletionRequest::new(messages)
1559	                .with_max_tokens(effective_max_tokens)
1560	                .with_temperature(0.3);
1561	
1562	            let response =
1563	                ctx.llm
1564	                    .complete(request)
1565	                    .await
1566	                    .map_err(|e| RoutineError::LlmFailed {
1567	                        retryable: crate::llm::retry::is_retryable(&e),
1568	                        reason: e.to_string(),
1569	                        partial_tokens: tokens_to_option(total_input_tokens, total_output_tokens),
1570	                    })?;
1571	
1572	            total_input_tokens += response.input_tokens;
1573	            total_output_tokens += response.output_tokens;
1574	
1575	            return handle_text_response(
1576	                &response.content,
1577	                response.finish_reason,
1578	                total_input_tokens,
1579	                total_output_tokens,
1580	            );
1581	        } else {
1582	            // Tool-enabled iteration
1583	            let tool_defs = ctx
1584	                .tools
1585	                .tool_definitions()
1586	                .await
1587	                .into_iter()
1588	                .filter(|tool| allowed_tools.contains(&tool.name))
1589	                .collect();
1590	
1591	            let request_messages = snapshot_messages_for_tool_iteration(&messages);
1592	            let request = ToolCompletionRequest::new(request_messages, tool_defs)
1593	                .with_max_tokens(effective_max_tokens)
1594	                .with_temperature(0.3);
1595	
1596	            let response = ctx.llm.complete_with_tools(request).await.map_err(|e| {
1597	                RoutineError::LlmFailed {
1598	                    retryable: crate::llm::retry::is_retryable(&e),
1599	                    reason: e.to_string(),
1600	                    partial_tokens: tokens_to_option(total_input_tokens, total_output_tokens),
1601	                }
1602	            })?;
1603	
1604	            total_input_tokens += response.input_tokens;
1605	            total_output_tokens += response.output_tokens;
1606	
1607	            // Check if LLM returned text (no tool calls)
1608	            if response.tool_calls.is_empty() {
1609	                let content = response.content.unwrap_or_default();
1610	                return handle_text_response(
1611	                    &content,
1612	                    response.finish_reason,
1613	                    total_input_tokens,
1614	                    total_output_tokens,
1615	                );
1616	            }
1617	
1618	            // LLM returned tool calls: add assistant message and execute tools
1619	            messages.push(ChatMessage::assistant_with_tool_calls(
1620	                response.content.clone(),
1621	                response.tool_calls.clone(),
1622	            ));
1623	
1624	            // Execute tools sequentially
1625	            for tc in response.tool_calls {
1626	                let result = execute_routine_tool(ctx, &job_ctx, &allowed_tools, &tc).await;
1627	
1628	                // Sanitize and wrap result (including errors)
1629	                let result_content = match result {
1630	                    Ok(output) => {
1631	                        let sanitized = ctx.safety.sanitize_tool_output(&tc.name, &output);
1632	                        ctx.safety.wrap_for_llm(&tc.name, &sanitized.content)
1633	                    }
1634	                    Err(e) => {
1635	                        let error_msg = format!("Tool '{}' failed: {}", tc.name, e);
1636	                        let sanitized = ctx.safety.sanitize_tool_output(&tc.name, &error_msg);
1637	                        ctx.safety.wrap_for_llm(&tc.name, &sanitized.content)
1638	                    }
1639	                };
1640	
1641	                // Truncate oversized tool output to prevent unbounded context growth.
1642	                // Routine tool loops are lightweight and should not accumulate
1643	                // large payloads across iterations.
1644	                const MAX_TOOL_OUTPUT_CHARS: usize = 8192;
1645	                let result_content = if result_content.len() > MAX_TOOL_OUTPUT_CHARS {
1646	                    let truncated = &result_content
1647	                        [..result_content.floor_char_boundary(MAX_TOOL_OUTPUT_CHARS)];
1648	                    format!("{truncated}\n... [output truncated to {MAX_TOOL_OUTPUT_CHARS} chars]")
1649	                } else {
1650	                    result_content
1651	                };
1652	
1653	                // Add tool result to context
1654	                messages.push(ChatMessage::tool_result(&tc.id, &tc.name, &result_content));
1655	            }
1656	
1657	            // Continue loop to next LLM call
1658	        }
1659	    }
1660	}
1661	
1662	// Bound per-iteration context copy cost for lightweight tool loops.
1663	const MAX_TOOL_LOOP_MESSAGES: usize = 32;
1664	
1665	fn snapshot_messages_for_tool_iteration(messages: &[ChatMessage]) -> Vec<ChatMessage> {
1666	    if messages.len() <= MAX_TOOL_LOOP_MESSAGES {
1667	        return messages.to_vec();
1668	    }
1669	
1670	    let mut snapshot = Vec::with_capacity(MAX_TOOL_LOOP_MESSAGES);
1671	
1672	    if let Some(first) = messages.first()
1673	        && first.role == crate::llm::Role::System
1674	    {
1675	        snapshot.push(first.clone());
1676	        let tail_len = MAX_TOOL_LOOP_MESSAGES - 1;
1677	        let tail_start = (messages.len() - tail_len).max(1);
1678	        snapshot.extend_from_slice(&messages[tail_start..]);
1679	    } else {
1680	        let tail_start = messages.len() - MAX_TOOL_LOOP_MESSAGES;
1681	        snapshot.extend_from_slice(&messages[tail_start..]);
1682	    }
1683	
1684	    snapshot
1685	}
