1687	/// Execute a single tool for a lightweight routine.
1688	async fn execute_routine_tool(
1689	    ctx: &EngineContext,
1690	    job_ctx: &JobContext,
1691	    allowed_tools: &std::collections::HashSet<String>,
1692	    tc: &ToolCall,
1693	) -> Result<String, Box<dyn std::error::Error + Send + Sync>> {
1694	    if !allowed_tools.contains(&tc.name) {
1695	        let message = autonomous_unavailable_message(&tc.name, &job_ctx.user_id);
1696	        return Err(message.into());
1697	    }
1698	
1699	    // Check if tool exists
1700	    let tool = ctx
1701	        .tools
1702	        .get(&tc.name)
1703	        .await
1704	        .ok_or_else(|| format!("Tool '{}' not found", tc.name))?;
1705	    let normalized_params = prepare_tool_params(tool.as_ref(), &tc.arguments);
1706	
1707	    // Validate tool parameters
1708	    let validation = ctx
1709	        .safety
1710	        .validator()
1711	        .validate_tool_params(&normalized_params);
1712	    if !validation.is_valid {
1713	        let details = validation
1714	            .errors
1715	            .iter()
1716	            .map(|e| format!("{}: {}", e.field, e.message))
1717	            .collect::<Vec<_>>()
1718	            .join("; ");
1719	        return Err(format!("Invalid tool parameters: {}", details).into());
1720	    }
1721	
1722	    // Execute with per-tool timeout
1723	    let timeout = tool.execution_timeout();
1724	    let start = std::time::Instant::now();
1725	    let result = tokio::time::timeout(timeout, async {
1726	        tool.execute(normalized_params.clone(), job_ctx).await
1727	    })
1728	    .await;
1729	    let elapsed = start.elapsed();
1730	
1731	    // Log tool execution result (single consolidated log)
1732	    match &result {
1733	        Ok(Ok(_)) => {
1734	            tracing::debug!(
1735	                tool = %tc.name,
1736	                elapsed_ms = elapsed.as_millis() as u64,
1737	                status = "succeeded",
1738	                "Lightweight routine tool execution completed"
1739	            );
1740	        }
1741	        Ok(Err(e)) => {
1742	            tracing::debug!(
1743	                tool = %tc.name,
1744	                elapsed_ms = elapsed.as_millis() as u64,
1745	                error = %e,
1746	                status = "failed",
1747	                "Lightweight routine tool execution completed"
1748	            );
1749	        }
1750	        Err(_) => {
1751	            tracing::debug!(
1752	                tool = %tc.name,
1753	                elapsed_ms = elapsed.as_millis() as u64,
1754	                timeout_secs = timeout.as_secs(),
1755	                status = "timeout",
1756	                "Lightweight routine tool execution completed"
1757	            );
1758	        }
1759	    }
1760	
1761	    let result = result
1762	        .map_err(|_| ToolError::Timeout(timeout))
1763	        .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?
1764	        .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;
1765	
1766	    // Serialize result to JSON string
1767	    let result_str =
1768	        serde_json::to_string(&result.result).unwrap_or_else(|_| "<serialize error>".to_string());
1769	    Ok(result_str)
1770	}
