1772	/// Send a notification based on the routine's notify config and run status.
1773	async fn send_notification(
1774	    tx: &mpsc::Sender<OutgoingResponse>,
1775	    notify: &NotifyConfig,
1776	    owner_id: &str,
1777	    routine_name: &str,
1778	    status: RunStatus,
1779	    summary: Option<&str>,
1780	    thread_id: Option<&str>,
1781	) {
1782	    let should_notify = match status {
1783	        RunStatus::Ok => notify.on_success,
1784	        RunStatus::Attention => notify.on_attention,
1785	        RunStatus::Failed => notify.on_failure,
1786	        RunStatus::Running => false,
1787	    };
1788	
1789	    if !should_notify {
1790	        return;
1791	    }
1792	
1793	    let icon = match status {
1794	        RunStatus::Ok => "✅",
1795	        RunStatus::Attention => "🔔",
1796	        RunStatus::Failed => "❌",
1797	        RunStatus::Running => "⏳",
1798	    };
1799	
1800	    let message = match summary {
1801	        Some(s) => format!("{} *Routine '{}'*: {}\n\n{}", icon, routine_name, status, s),
1802	        None => format!("{} *Routine '{}'*: {}", icon, routine_name, status),
1803	    };
1804	
1805	    let response = OutgoingResponse {
1806	        content: message,
1807	        thread_id: thread_id.map(String::from),
1808	        attachments: Vec::new(),
1809	        metadata: serde_json::json!({
1810	            "source": "routine",
1811	            "routine_name": routine_name,
1812	            "status": status.to_string(),
1813	            "owner_id": owner_id,
1814	            "notify_user": notify.user,
1815	            "notify_channel": notify.channel,
1816	        }),
1817	    };
1818	
1819	    if let Err(e) = tx.send(response).await {
1820	        tracing::error!(routine = %routine_name, "Failed to send notification: {}", e);
1821	    }
1822	}
