1824	/// Spawn the cron ticker background task.
1825	pub fn spawn_cron_ticker(
1826	    engine: Arc<RoutineEngine>,
1827	    interval: Duration,
1828	) -> tokio::task::JoinHandle<()> {
1829	    tokio::spawn(async move {
1830	        // Recover orphaned runs from a previous process crash before
1831	        // dispatching any new work, so we don't confuse fresh dispatches
1832	        // with crash orphans.
1833	        engine.sync_dispatched_runs().await;
1834	
1835	        // Run one cron check immediately so routines due at startup don't
1836	        // wait an extra full polling interval.
1837	        engine.check_cron_triggers().await;
1838	
1839	        let mut ticker = tokio::time::interval(interval);
1840	        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
1841	        // Periodic event cache refresh so web/CLI mutations are picked up
1842	        // without requiring tool-path code to call refresh_event_cache().
1843	        // Uses wall-clock elapsed time so the refresh cadence is stable
1844	        // regardless of the cron tick interval configuration.
1845	        let refresh_interval = Duration::from_secs(60);
1846	        let mut last_refresh = tokio::time::Instant::now();
1847	
1848	        loop {
1849	            ticker.tick().await;
1850	            // Sync first: only processes runs from before boot_time, so it
1851	            // never races with FullJobWatcher instances from this process.
1852	            engine.sync_dispatched_runs().await;
1853	            engine.check_cron_triggers().await;
1854	
1855	            if last_refresh.elapsed() >= refresh_interval {
1856	                engine.refresh_event_cache().await;
1857	                last_refresh = tokio::time::Instant::now();
1858	            }
1859	        }
1860	    })
1861	}
