1906	/// Remove HTML/XML tags from a string.
1907	#[cfg(test)]
1908	fn strip_html_tags(s: &str) -> String {
1909	    let mut result = String::with_capacity(s.len());
1910	    let mut in_tag = false;
1911	    for c in s.chars() {
1912	        match c {
1913	            '<' => in_tag = true,
1914	            '>' if in_tag => in_tag = false,
1915	            _ if !in_tag => result.push(c),
1916	            _ => {}
1917	        }
1918	    }
1919	    result
1920	}
