344	    /// Schedule a sub-task from within a worker.
345	    ///
346	    /// Sub-tasks are lightweight tasks that don't go through the full job lifecycle.
347	    /// They're used for parallel tool execution and background computations.
348	    ///
349	    /// Returns a oneshot receiver to get the result.
350	    pub async fn spawn_subtask(
351	        &self,
352	        parent_id: Uuid,
353	        task: Task,
354	    ) -> Result<oneshot::Receiver<Result<TaskOutput, Error>>, JobError> {
355	        let task_id = Uuid::new_v4();
356	        let (result_tx, result_rx) = oneshot::channel();
357	
358	        let handle = match task {
359	            Task::Job { .. } => {
360	                // Jobs should go through schedule(), not spawn_subtask
361	                return Err(JobError::ContextError {
362	                    id: parent_id,
363	                    reason: "Use schedule() for Job tasks, not spawn_subtask()".to_string(),
364	                });
365	            }
366	
367	            Task::ToolExec {
368	                parent_id: tool_parent_id,
369	                tool_name,
370	                params,
371	            } => {
372	                let tools = self.tools.clone();
373	                let context_manager = self.context_manager.clone();
374	                let safety = self.safety.clone();
375	
376	                // TODO: propagate parent job's ApprovalContext here when subtasks
377	                // are used in autonomous/routine paths (currently only used in tests).
378	                tokio::spawn(async move {
379	                    let result = Self::execute_tool_task(
380	                        tools,
381	                        context_manager,
382	                        safety,
383	                        None,
384	                        tool_parent_id,
385	                        &tool_name,
386	                        params,
387	                    )
388	                    .await;
389	
390	                    // Send result (ignore if receiver dropped)
391	                    let _ = result_tx.send(result);
392	                })
393	            }
394	
395	            Task::Background { id: _, handler } => {
396	                let ctx = TaskContext::new(task_id).with_parent(parent_id);
397	
398	                tokio::spawn(async move {
399	                    let result = handler.run(ctx).await;
400	                    let _ = result_tx.send(result);
401	                })
402	            }
403	        };
404	
405	        // Track the subtask
406	        self.subtasks.write().await.insert(
407	            task_id,
408	            ScheduledSubtask {
409	                handle: tokio::spawn(async move {
410	                    // Wrap the handle to get its result
411	                    match handle.await {
412	                        Ok(()) => Err(Error::Job(JobError::ContextError {
413	                            id: task_id,
414	                            reason: "Subtask completed but result not captured".to_string(),
415	                        })),
416	                        Err(e) => Err(Error::Job(JobError::ContextError {
417	                            id: task_id,
418	                            reason: format!("Subtask panicked: {}", e),
419	                        })),
420	                    }
421	                }),
422	            },
423	        );
424	
425	        // Cleanup task for subtask tracking
426	        let subtasks = Arc::clone(&self.subtasks);
427	        tokio::spawn(async move {
428	            loop {
429	                let finished = {
430	                    let subtasks_read = subtasks.read().await;
431	                    match subtasks_read.get(&task_id) {
432	                        Some(scheduled) => scheduled.handle.is_finished(),
433	                        None => true,
434	                    }
435	                };
436	
437	                if finished {
438	                    subtasks.write().await.remove(&task_id);
439	                    break;
440	                }
441	
442	                tokio::time::sleep(Duration::from_secs(1)).await;
443	            }
444	        });
445	
446	        tracing::debug!(
447	            parent_id = %parent_id,
448	            task_id = %task_id,
449	            "Spawned subtask"
450	        );
451	
452	        Ok(result_rx)
453	    }
454	
455	    /// Schedule multiple tasks in parallel and wait for all to complete.
456	    ///
457	    /// Returns results in the same order as the input tasks.
458	    pub async fn spawn_batch(
459	        &self,
460	        parent_id: Uuid,
461	        tasks: Vec<Task>,
462	    ) -> Vec<Result<TaskOutput, Error>> {
463	        if tasks.is_empty() {
464	            return Vec::new();
465	        }
466	
467	        let mut receivers = Vec::with_capacity(tasks.len());
468	
469	        // Spawn all tasks
470	        for task in tasks {
471	            match self.spawn_subtask(parent_id, task).await {
472	                Ok(rx) => receivers.push(Some(rx)),
473	                Err(e) => {
474	                    // Store the error directly
475	                    receivers.push(None);
476	                    tracing::warn!(
477	                        parent_id = %parent_id,
478	                        error = %e,
479	                        "Failed to spawn subtask in batch"
480	                    );
481	                }
482	            }
483	        }
484	
485	        // Collect results
486	        let mut results = Vec::with_capacity(receivers.len());
487	        for rx in receivers {
488	            let result = match rx {
489	                Some(receiver) => match receiver.await {
490	                    Ok(task_result) => task_result,
491	                    Err(_) => Err(Error::Job(JobError::ContextError {
492	                        id: parent_id,
493	                        reason: "Subtask channel closed unexpectedly".to_string(),
494	                    })),
495	                },
496	                None => Err(Error::Job(JobError::ContextError {
497	                    id: parent_id,
498	                    reason: "Subtask failed to spawn".to_string(),
499	                })),

